"""Generate the independently audited occurrence data for records 2--14.
Run from the workspace; output is captured in generation_output.txt.
All mathematical text is editorial input, not automatically inferred from OCR.
"""
import json
from pathlib import Path
from collections import Counter

OUT=Path(__file__).resolve().parent
talks=[]; items=[]; problems=[]
def talk(r,date,speaker,pages,title,summary):
    talks.append(dict(record=r,date=date,speaker=speaker,pages=pages,title=title,kind='talk',summary=summary))
def item(r,n,pages,kind,title,notes,statement,cl,fate,status,refs=(),reconstruction='',literal='correct with missing hypotheses',match='partial',verification='read the result',confidence='high',problem='',worth='',development='annotated'):
    items.append(dict(id=f'1964-{r}.{n}',record=r,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cl},fate=fate,present_status='As of November 2026: '+status,literal_correctness=literal,publication_match=match,verification=verification,development=development,problem=problem,worth=worth,refs=list(refs),confidence=confidence))
def save():
    for name,data in [('talks',talks),('items',items),('problems',problems)]:
        (OUT/(name+'.json')).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    print(f'Saved {len(talks)} talks, {len(items)} items, {len(problems)} problems; latest record {talks[-1]["record"]}')

talk(2,'1964-09-21','I. M. Gelfand','P000001-P000004','Resolution, blowups, and projective spectra',r'''After a group-theoretic heading, the notes discuss Hironaka's resolution theorem through the universal property of blowing up, graded algebras and two explicit centers. The algebraic examples occupy P000001--P000003; Dobrushin begins on P000003. The distinction between a symmetric algebra and a Rees algebra matters, and the crossing-center example is not itself a resolution.''')
item(2,1,'P000001','remark','Cartesian and Boolean products of groups',r'''Only the heading \ru{Декартово и булево произведение групп} survives before the change to resolution.''',r'''No groups, category, construction of a Boolean product, or assertion are specified. The phrase cannot determine one mathematical item more precisely.''','F',r'''Title searches distinguish several uses of Boolean products; none can identify the intended construction from this heading. No publication match is asserted.''','Unidentified heading, rather than evidence of an undeveloped problem.',literal='not determinable',match='none found',verification='unresolved lead',confidence='low',development='none')
item(2,2,'P000001','theorem','Hironaka resolution in characteristic zero',r'''A singular divisor \(D\) is replaced by a smooth hypersurface over it, under the heading Hironaka. The base field and the distinction between total and strict transforms are not stated.''',r'''For a reduced variety over a characteristic-zero field, resolution gives a proper birational morphism from a smooth variety, an isomorphism over a prescribed smooth locus. In embedded resolution of a divisor in a smooth ambient variety, the strict transform is smooth and the total transform has simple normal crossings after suitable blowups; the total inverse image need not be a smooth hypersurface.''','E',r'''The named result had appeared in \citet{hironaka1964resolution}, Part I, introduction and main theorem, in 1964, before this September discussion; the Russian translation followed in 1965. The opened archive record verifies the publication, not every proof in the 95-page paper.''','The characteristic-zero theorem is established. Removing the characteristic-zero hypothesis is a different question and is not posed here.',refs=['hironaka1964resolution'],literal='correct with missing hypotheses',verification='publisher metadata checked',reconstruction='The field hypothesis and strict/total-transform distinction are editorial precisions.',match='exact')
item(2,3,'P000001-P000002','construction','Universal blowup and invertibility of the center',r'''The notebook seeks \(V'\to V\) making an ideal \(J\) locally principal, with a universal mapping property, and then writes its symmetric tensor algebra.''',r'''For a scheme \(X\) and a finite-type quasi-coherent ideal \(I\), the blowup is \(\operatorname{Proj}_X\mathcal R(I)\), where \(\mathcal R(I)=\bigoplus_{n\ge0}I^n\). It is terminal among \(X\)-schemes on which the inverse-image ideal defines an effective Cartier divisor. Locally principal alone is insufficient when a generator is a zero divisor. In general \(\operatorname{Sym}(I)\twoheadrightarrow\mathcal R(I)\) is not an isomorphism.''','E',r'''This is the standard blowup universal property, recorded precisely in \citet[tags 01OF and 0806]{stacks2026blowups}. The modern reference is used to correct the algebra, not to date its invention.''','Established construction. The symmetric algebra works for ideals of linear type, including the two regular-sequence examples below.',refs=['stacks2026blowups'],literal='false as written',match='exact',reconstruction='Replace the symmetric algebra by the Rees algebra in the general assertion; retain the original notation in the notes field.')
item(2,4,'P000002','construction','Proj, homogeneous primes, and the local sheaf',r'''Homogeneous prime ideals and homogeneous fractions of equal degree are discussed; the abbreviation \ru{Выбр.} precedes primes containing all positive-degree elements.''',r'''For a positively graded ring \(S\), \(\operatorname{Proj}S\) consists of homogeneous primes not containing \(S_+=\bigoplus_{d>0}S_d\). On \(D_+(f)\), \(\mathcal O\) is the degree-zero part of \(S_f\); the degree-one component gives \(\mathcal O(1)\), with the usual degree conventions.''','E',r'''The projective-spectrum construction underlying \citet[Section 31.33]{stacks2026blowups} predates the lecture. The scan supports the abbreviation but does not justify expanding it as ``choose'' rather than ``discard.''''','Standard scheme construction; reversing the irrelevant-ideal exclusion would destroy the intended Proj.',refs=['stacks2026blowups'],reconstruction='The intended exclusion and the distinction between degree zero and degree one are explicit modern reconstructions.',literal='correct with missing hypotheses',match='partial')
item(2,5,'P000002-P000003','construction','Blowing up the origin of the affine plane',r'''For the ideal of the origin in the plane the exceptional fiber is a projective line and local coordinate ratios are introduced.''',r'''For \(I=(x,y)\subset k[x,y]\), \(\operatorname{Bl}_0\mathbb A^2\subset\mathbb A^2\times\mathbb P^1\) has equation \(xV=yU\). Its two charts are \(y=xv\) and \(x=yu\), each an affine plane, and the fiber over the origin is \(\mathbb P^1_k\).''','E',r'''This is the affine-chart construction of \citet[Lemma 31.33.2]{stacks2026blowups}; the notebook example is an exposition of it.''','The calculation is valid over any field and gives a smooth blowup.',refs=['stacks2026blowups'],literal='correct',match='exact',reconstruction='The homogeneous-coordinate equation and chart equations spell out the drawing.')
item(2,6,'P000003','construction','Blowing up the crossing ideal (z,xy)',r'''The next center is \(z=0,xy=0\), the union of two lines, with the two generators \(z,xy\).''',r'''For \(I=(z,xy)\subset k[x,y,z]\), the Rees presentation is \(k[x,y,z,U,V]/(xyU-zV)\). On \(U\ne0\) the chart is \(xy=zv\); on \(V\ne0\) it is \(z=xyu\). The former has a singular point at the origin; therefore this single blowup is not a general resolution procedure.''','E',r'''The example is an application of the blowup charts in \citet[Lemma 31.33.2]{stacks2026blowups}. No later publication is needed to account for it.''','The calculation remains a useful warning that an arbitrary center can produce a singular blowup.',refs=['stacks2026blowups'],literal='correct with missing hypotheses',match='partial',reconstruction='The Rees relation, two charts, and singular-point diagnosis are editorial algebraic checks; the notebook does not claim a completed resolution.')
save()

talk(3,'1964-09-21','R. L. Dobrushin','P000002-P000012','Canonical Ising coexistence, contours, and a no-return walk',r'''Dobrushin develops the canonical lattice gas, a criterion for phase coexistence through macroscopic density fluctuations, and the contour estimates underlying his 1965 phase-transition paper. A short walk question follows. Signs and the density/specific-volume notation vary between pages, so the modern statements fix one convention. The walk question lacks enough information to identify its probability law uniquely.''')
item(3,1,'P000003-P000004','definition','Canonical lattice gas and Ising energy',r'''There are \(N\) particles at distinct sites of a lattice box of volume \(V\), with energy minus the number of occupied nearest-neighbor pairs and weights \(e^{-U/T}\).''',r'''Let \(\Lambda\subset\mathbb Z^\nu\) be finite, \(\eta_x\in\{0,1\}\), \(\sum_x\eta_x=N\), and \(H_\Lambda(\eta)=-\sum_{\{x,y\}\subset\Lambda,\,|x-y|_1=1}\eta_x\eta_y\). At \(T>0\), \(Z_{\Lambda,N}=\sum e^{-H_\Lambda/T}\) and the canonical law is the normalized weight. With \(\eta_x=(1+\sigma_x)/2\) this is an Ising model with the corresponding fixed magnetization and boundary terms.''','E',r'''The model is the starting point of \citet[Section 1]{dobrushin1965phase}; its definition predates the lecture. That paper was received on 30 September 1964 and published in 1965.''','Standard finite-volume probability law; the sum counts configurations once, not ordered particle labels.',refs=['dobrushin1965phase'],literal='correct',match='exact')
item(3,2,'P000004-P000006','theorem','Thermodynamic limit and independence of regular shape',r'''The notes introduce \(f(v,T)=\lim N^{-1}\log Z\), \(v=V/N\), assert independence of the expanding region, and call the resulting function convex.''',r'''For this finite-range lattice gas along regular expanding boxes, with \(N/|\Lambda|\to\rho\in(0,1)\), the canonical log-partition density \(s_T(\rho)=\lim|\Lambda|^{-1}\log Z_{\Lambda,N}\) exists and is concave. Its perspective \(f(v,T)=v s_T(1/v)\), \(v>1\), is concave. Boundary changes of order \(|\partial\Lambda|\) do not affect the limit for van Hove sequences.''','E',r'''\citet[Section 1]{dobrushin1965phase} explicitly uses the thermodynamic limit as prior input. The positive-log convention in the notebook forces concavity; its later minus sign cannot be retained simultaneously.''','Established for the stated finite-range interaction and regular limits. Arbitrary irregular regions need not have negligible boundary effects.',refs=['dobrushin1965phase'],literal='false as written',match='exact',reconstruction='A single positive-log convention is imposed; regularity of the exhausting sequence is supplied.')
item(3,3,'P000004-P000008','claim','Coexistence plateau and the meaning of one transition',r'''A pressure plateau is drawn and the van der Waals picture is compared with the lattice model; one line later says \(\partial f/\partial v=0\).''',r'''For \(F=-NT f(v,T)\), pressure is \(p=T\partial_v f\) wherever the derivative exists. A coexistence interval is an affine segment of \(f\), hence a constant-pressure interval; the pressure need not be zero. In density variables, the grand-canonical transition corresponds to distinct equilibrium densities at one chemical potential.''','E',r'''The thermodynamic interpretation is the framework of \citet[Section 1 and Theorem 1]{dobrushin1965phase}. The general claim of exactly one transition is not justified by the sketch alone.''','Phase coexistence is rigorous at sufficiently low temperature in the models discussed; the picture is not a proof of a complete phase diagram.',refs=['dobrushin1965phase'],literal='false as written',match='partial',reconstruction='The relationship between canonical and grand-canonical variables is made explicit; ``zero derivative'' is replaced by ``constant derivative.''')
item(3,4,'P000004','theorem','No positive-temperature transition in one dimension',r'''The one-dimensional model is said to have no phase transition at positive temperature.''',r'''The nearest-neighbor one-dimensional Ising model has analytic infinite-volume pressure for every finite real field and \(T>0\), because its positive transfer matrix has a simple Perron eigenvalue. Its canonical free energy has no low-temperature coexistence segment of the type sought in dimensions two and three.''','E',r'''This classical contrast is part of the introduction in \citet{dobrushin1965phase}; the transfer-matrix mechanism predates 1964.''','Established for finite-range one-dimensional Ising interactions; long-range interactions are outside the statement.',refs=['dobrushin1965phase'],literal='correct with missing hypotheses',match='partial')
item(3,5,'P000004','remark','Onsager and Kac--Helfand antecedents',r'''Onsager's two-dimensional result and work attributed to Kac and Helfand are named as earlier achievements, without a complete bibliographic or parameter specification.''',r'''Onsager solved the zero-field nearest-neighbor square-lattice Ising free energy. The Kac--Helfand reference is an antecedent in the discussion of phase transition, but the notebook alone does not identify a particular long-range limiting regime.''','E',r'''The prior literature is discussed in \citet[Section 1 and bibliography]{dobrushin1965phase}. The Onsager identification is secure; a unique Kac--Helfand theorem is not inferred merely from the names.''','The historical comparison is expository. It must not be read as an exact solution of the three-dimensional model.',refs=['dobrushin1965phase'],literal='not determinable',match='partial',confidence='medium')
item(3,6,'P000005-P000006','theorem','Macroscopic density deviations and coexistence',r'''The number of particles in a macroscopic subcube is compared with its expected density. Failure of a volume-scale exponential deviation bound is used to detect a linear piece of the limiting free energy.''',r'''For a fixed volume fraction \(a\in(0,1)\), compare a density split \(\rho=a\rho_1+(1-a)\rho_2\). Up to subvolume boundary errors the log probability has volume rate \(a s_T(\rho_1)+(1-a)s_T(\rho_2)-s_T(\rho)\). Strict inequality gives exponential suppression; equality along an interval is the canonical signature of coexistence. The criterion requires the allowed density splits and thermodynamic sequences to be specified.''','A',r'''The matching criterion appears in \citet[Theorem 2 and the reduction following it]{dobrushin1965phase}, received nine days after the seminar and published in 1965.''','The criterion is established in this lattice-gas setting. A failure of an unspecified law of large numbers in an arbitrary model is not an equivalent theorem.',refs=['dobrushin1965phase'],match='exact',reconstruction='The rate function and the precise role of concavity replace compressed probability notation.')
item(3,7,'P000005-P000006','method','Boundary-energy factorization of partition functions',r'''The partition sum is split into a subbox and its complement, with a factor \(\exp\{\theta N^{2/3}\}\) accounting for crossing bonds.''',r'''For fixed particle allocations \(k,N-k\), removing all bonds crossing an interface changes each Gibbs weight by factors between \(e^{-C|\partial H|/T}\) and \(e^{C|\partial H|/T}\). The restricted partition sum is therefore comparable to \(Z_{H,k}Z_{\Lambda\setminus H,N-k}\). For geometrically similar boxes in \(\nu\) dimensions the exponent is \(O(N^{(\nu-1)/\nu})\), and \(2/3\) is the three-dimensional case.''','A',r'''This is the finite-range comparison used in \citet[proof of Theorem 2]{dobrushin1965phase}; the 1965 publication supplies the boundary bookkeeping.''','A standard and valid surface-error estimate. It is negligible only at volume scale, not at the surface scale of interface fluctuations.',refs=['dobrushin1965phase'],match='exact',reconstruction='The dependence on dimension and temperature is restored.')
item(3,8,'P000006-P000010','method','Large and small contours force spatial separation',r'''Contours are divided at a cutoff \(M\); a large contour has surface of order \(l^{\nu-1}\), while the total enclosed volume of small contours is controlled by an isoperimetric sum. Earlier exponents differ from the later restatement.''',r'''For closed interfaces of surface sizes \(|\Gamma_i|\), isoperimetry bounds enclosed volumes by \(S_\nu|\Gamma_i|^{\nu/(\nu-1)}\), with geometry-dependent lattice constants. If the small-contour contribution cannot accommodate the minority phase, a macroscopic interface or separated dense and dilute regions must occur. A surface in a box of side \(l\) has scale \(l^{\nu-1}\), not \(l^{(\nu-1)/\nu}\).''','A',r'''The contour decomposition and geometric estimates belong to \citet[Sections 2--4]{dobrushin1965phase}. The later notebook restatement is used to diagnose the earlier exponent, not to conceal it.''','Established proof strategy for low-temperature coexistence. Precise constants depend on the contour convention and cannot be transferred unchanged between lattice surfaces and Euclidean spheres.',refs=['dobrushin1965phase'],literal='false as written',match='exact',reconstruction='Only the geometric implication common to the displayed estimates is asserted; overwritten summation limits are not silently completed.')
item(3,9,'P000009-P000011','method','Contour entropy against Boltzmann cost',r'''The proof counts contours by exponential bounds, including \(3^k\), and compares their multiplicity with the energetic penalty.''',r'''A rooted planar nearest-neighbor contour with a prescribed first edge has at most \(3^{k-1}\) nonbacktracking continuations of length \(k\); self-avoidance only decreases that number. In higher dimensions a separate connected-surface enumeration supplies \(C^k\). If the energy cost per unit interface exceeds \(T\log C\), the contour sum converges.''','A',r'''This is the entropy-energy estimate in \citet[Sections 3--4]{dobrushin1965phase}. The seminar's planar \(3^k\) cannot by itself enumerate arbitrary three-dimensional surfaces.''','Rigorous with a specified root and contour class; it is the low-temperature Peierls mechanism.',refs=['dobrushin1965phase'],literal='correct with missing hypotheses',match='exact')
item(3,10,'P000008-P000010','theorem','An explicit low-temperature coexistence window',r'''A function \(Q(T)\), defined by a convergent contour series, gives a nontrivial density interval \(Q(T)<1/v<1-Q(T)\) when \(T\) is sufficiently small.''',r'''For the nearest-neighbor attractive lattice gas in dimensions two and three, the stated contour estimates give a positive-temperature interval in which the thermodynamic canonical free energy has a coexistence segment. The explicit sufficient condition is \(Q(T)<1/2\), with \(Q\) defined in the published theorem; it is not the exact critical temperature.''','A',r'''The direct match is \citet[Theorem 1, equations (1.6)--(1.7)]{dobrushin1965phase}. Its receipt date is 30 September 1964 and publication year 1965.''','The sufficient window is established. The conflicting manuscript energy sign and compressed parentheses should be reconciled with the published definition before using numerical constants.',refs=['dobrushin1965phase'],match='exact',reconstruction='The dependable interval is stated without pretending that the partly ambiguous handwritten series fixes every constant.')
item(3,11,'P000011','problem','Expected displacement of a walk with returns forbidden',r'''The notebook labels an unsolved question: turn with probability \(1/3\), returning forbidden, and estimate expected distance after \(N\) steps. It compares the unrestricted walk with \(\sqrt N\).''',r'''The written rule does not determine a probability measure: forbidding only immediate reversals, forbidding every revisit during growth, and choosing uniformly among all length-\(N\) self-avoiding walks give different laws. A definite modern problem associated with the passage is to determine the displacement exponent of uniform nearest-neighbor self-avoiding walks on \(\mathbb Z^2\). That association does not identify the original law uniquely.''','C',r'''The surrounding contour-counting discussion supports a self-avoidance connection, but the ambiguous rule prevents an exact publication match. Later rigorous SAW work and the remaining exponent question are separated in problem GP-1964-01.''',r'For uniform planar SAW, the expected \(N^{3/4}\) displacement scale remains a conjectural identification in the sources reviewed; the notes do not state the exponent \(3/4\). The nonbacktracking interpretation is an elementary different problem.',literal='not determinable',match='partial',verification='unresolved lead',confidence='medium',problem='GP-1964-01',worth='The uniform-SAW problem remains significant, but a bounded companion contribution should clarify the law and known estimates rather than promise the planar exponent.',reconstruction='Uniform SAW and the exponent conjecture are modern comparisons, explicitly not words or a theorem in the notebook.')
item(3,12,'P000011','conjecture','The conjectured exponential count e^n',r'''The following line gives rough bases \(2.6\) and \(2.8\), followed by a conjecture \(e^n\); the phrase about allowing returns conflicts with this count.''',r'''If \(c_n\) counts nearest-neighbor self-avoiding walks of length \(n\) from the origin in \(\mathbb Z^2\), submultiplicativity defines \(\mu=\lim c_n^{1/n}\). The conjecture \(\mu=e\) is false by rigorous upper bounds below \(e\). If immediate reversals alone are prohibited, the count is exactly \(4\cdot3^{n-1}\), also incompatible with \(e^n\).''','B',r'''The numerical range suggests square-lattice self-avoiding walks, but no unique law is imposed on the source. Modern rigorous bounds refute the proposed base under that interpretation; an exact connective constant for the square lattice is not thereby obtained.''',r'The base \(e\) is excluded for uniform square-lattice SAW counting, while the exact constant remains unknown in the reviewed literature.',literal='not determinable',match='partial',verification='unresolved lead',confidence='medium',problem='GP-1964-01',reconstruction='The connective-constant formulation is conditional on the self-avoiding-walk interpretation.')
save()

talk(4,'1964-09-28','Irving E. Segal','P000010-P000014','Nonlinear wave evolution and geometry of solutions',r'''A preliminary note explicitly dated Thursday 24 September appears on P000007--P000008; the main 28 September exposition starts on P000011. Both develop the nonlinear Klein--Gordon equation as an evolution in a Hilbert space, then its manifold of solutions, tangent equation, symplectic form and canonical quantization. These are linked to Segal's 1964--65 Leray seminar; they are not an unrestricted existence theorem for interacting quantum fields.''')
item(4,1,'P000007-P000008','construction','A quotient algebra for nonlinear equations',r'''The preliminary note encodes the field equation by functionals \(F_f\), forms a quotient \(\Phi/\Omega\), and interprets maximal ideals as generalized solutions.''',r'''For a specified commutative algebra \(\Phi\) of functionals on a classical configuration space, the ideal generated by weak equation functionals vanishes at every classical solution; evaluation gives a scalar-valued character of \(\Phi/\Omega\). The converse requires a specified character space and continuity or algebraic hypotheses. Infinite-dimensional maximal ideals need not be evaluations at ordinary fields.''','F',r'''The broad algebraic quantization program matches \citet[Parts I--III]{segal1965variete}, but the notebook does not define \(\Phi\), its topology or the allowed characters well enough to identify this maximal-ideal assertion as a theorem.''','The quotient construction is meaningful once its algebra is fixed. The asserted exhaustive solution interpretation is not established by the surviving text.',refs=['segal1965variete'],literal='not determinable',match='thematic only',confidence='medium',reconstruction='Only the implication from classical solutions to characters is retained unconditionally.')
item(4,2,'P000008; P000011','method','Semilinear evolution and Duhamel formula',r'''The field equation becomes \(u'=Au+K(u)\), with \(A=-A^*\), and an integral equation with \(e^{tA}\).''',r'''Let \(A\) generate a strongly continuous group on a Banach space and let \(K\) be locally Lipschitz. A mild solution satisfies \(u(t)=e^{(t-t_0)A}u_0+\int_{t_0}^t e^{(t-s)A}K(u(s))\,ds\), with local uniqueness. A strong solution needs the appropriate domain regularity; global existence needs an a priori bound preventing finite-time escape.''','E',r'''\citet[pp. 130--131]{segal1963global} explicitly formulates this abstract equation with skew-adjoint \(A\) and locally Lipschitz \(K\), citing his already circulating nonlinear-semigroup work.''','Established local theory. The nonlinear field map is not locally Lipschitz on every energy space in every dimension or for every power.',refs=['segal1963global'],match='exact',reconstruction='Mild/strong solutions and local/global existence are distinguished.')
item(4,3,'P000011-P000012','construction','The Klein--Gordon energy space and its generator',r'''With \(B=(m^2-\Delta)^{1/2}\), the notes write \(E=D(B)\oplus L^2\), an energy expression, and call the matrix generator self-adjoint.''',r'''For \(m>0\), put \(\|(\phi,\pi)\|_E^2=\|B\phi\|_2^2+\|\pi\|_2^2\). On \(D(B^2)\oplus D(B)\), \(A(\phi,\pi)=(\pi,-B^2\phi)\) is skew-adjoint in this energy inner product. Thus \(e^{tA}\) is unitary; \(iA\), after complexification, is self-adjoint.''','E',r'''The Hilbert-space formulation appears in \citet[pp. 130--132]{segal1963global}. Its sign agrees with P000011 and contradicts the later word ``self-adjoint.''''',r'Standard free Klein--Gordon evolution. For \(m=0\), the homogeneous energy completion requires a separate definition.',refs=['segal1963global'],literal='false as written',match='exact',reconstruction='The missing norm square, operator domain and skew-adjointness are supplied.')
item(4,4,'P000012','theorem','A smooth manifold of global solutions',r'''The totality \(M\) of solutions is a manifold, with evaluation at any time giving coordinates in \(E\).''',r'''If a semilinear evolution has a globally defined \(C^r\) flow \(\Phi_t:E\to E\), with \(\Phi_t\) a \(C^r\) diffeomorphism for every real \(t\), then the set of entire solutions inherits a \(C^r\) Banach-manifold structure via \(u\mapsto u(t_0)\). Local flows give only the corresponding local solution manifold.''','A',r'''The solution-manifold program is developed in \citet[Part II]{segal1965variete}, a 1964--65 lecture text, and in the related 1965 journal paper cited there. The formal assertion is conditional on the analytic hypotheses.''','Established under smooth global well-posedness; neither global existence nor a smooth flow follows merely from writing the differential equation.',refs=['segal1965variete'],match='exact',reconstruction='The required flow hypotheses are explicit rather than attributed to the abbreviated notes.')
item(4,5,'P000012','theorem','The variational equation identifies tangent vectors',r'''The tangent equation is written schematically as \(v'=Av+K'_u\), omitting application of the derivative to \(v\).''',r'''For a differentiable flow of \(u'=Au+K(u)\), the derivative in initial data solves \(v'=Av+DK(u(t))v\). Tangent vectors to the solution manifold at \(u\) are these linearized solutions, in the regularity class in which differentiation of the flow is justified.''','A',r'''This geometric linearization is part of \citet[Part II]{segal1965variete}. Its omission in the notebook is a missing factor, not an alternative evolution equation.''','A standard variational equation under differentiable well-posedness.',refs=['segal1965variete'],literal='false as written',match='exact',reconstruction=r'Restore the factor \(v\) and the derivative-of-flow hypothesis.')
item(4,6,'P000012-P000013','construction','Symplectic form, Poisson brackets and vector fields',r'''A skew form on tangent solutions is asserted independent of time and used to form Poisson brackets and associated vector fields.''',r'''For a Hamiltonian scalar-wave evolution whose linearized potential is symmetric, \(\Omega(v,w)=\int(v_1w_2-v_2w_1)\,dx\) is conserved. On an infinite-dimensional energy manifold it may be weakly symplectic: a functional has a Hamiltonian vector field only if its derivative lies in the range of \(v\mapsto\Omega(v,\cdot)\).''','A',r'''\citet[Part II, discussion of the form and Poisson brackets]{segal1965variete} develops this construction. Arbitrary \(K\) in the preceding abstract evolution need not preserve a symplectic form.''','Established Hamiltonian construction with domain and range conditions; it does not make every differentiable functional Hamiltonian.',refs=['segal1965variete'],match='exact',reconstruction='The Hamiltonian and weak-symplectic qualifications are supplied.')
item(4,7,'P000013','construction','Canonical commutation relations from the solution geometry',r'''The classical form and associated differential operators lead to canonical commutation relations, with an explicit operator construction sketched.''',r'''On a real symplectic space, the Weyl relations are \(W(f)W(g)=e^{-i\Omega(f,g)/2}W(f+g)\). Infinitesimal field commutators require common invariant domains. A representation and a state are extra choices; infinite-dimensional CCR do not have the finite-dimensional uniqueness property.''','A',r'''The concrete field construction is treated in \citet[Part III, theorem on printed p. 45]{segal1965variete}, circulated as 1964--65 lectures. The source's finite-dimensional analogy does not establish equivalence of all field representations.''','The CCR algebra and its representations are established, but this alone does not construct a renormalized interacting field theory.',refs=['segal1965variete'],match='partial',reconstruction='The Weyl form is a modern precise comparison; it is not a claim that the notebook contains all domain arguments.')
save()

talk(5,'1964-10-05','Irving E. Segal','P000012-P000014','Scattering and canonical fields',r'''The short continuation on P000013 mentions renormalization, scattering, generalized probabilities, particle interpretation and equal-time commutators. Several headings state intentions without enough hypotheses for a theorem. The classical wave-operator construction can be identified more precisely than the asserted quantum existence and uniqueness.''')
item(5,1,'P000013','claim','Existence and uniqueness for a renormalized cubic field',r'''Existence, uniqueness and renormalization of a nonlinear field are listed, with no cutoff scheme, dimension, operator domain or theorem statement.''',r'''No single existence theorem can be recovered: classical \(\phi^3\) evolution, a formal operator-valued equation, a regularized Hamiltonian, and a renormalized quantum field are distinct objects.''','F',r'''\citet[Parts III--V]{segal1965variete} provides a close contemporary program, but the headings do not identify an exact renormalization result.''','No unconditional quantum-field existence or uniqueness is inferred from this passage.',refs=['segal1965variete'],literal='not determinable',match='thematic only',confidence='low',development='none')
item(5,2,'P000013','construction','The classical scattering transformation',r'''A scattering map \(S\) compares asymptotic free fields in the distant past and future.''',r'''If the nonlinear flow admits incoming and outgoing wave operators \(W_-\) and \(W_+\), with the needed injectivity and range agreement, then the scattering transformation on their common asymptotic data space is \(S=W_+^{-1}W_-\). Existence and completeness depend on the interaction, dimension, sign, size and decay of the data.''','A',r'''\citet[Part IV, printed pp. 51--60]{segal1965variete} treats asymptotic solutions; \citet{segal1968dispersion} is a later systematic dispersion paper. The latter's metadata were checked, not its complete proof.''','The definition is standard; the unspecified notebook interaction does not support unrestricted asymptotic completeness.',refs=['segal1965variete','segal1968dispersion'],match='partial',reconstruction='The common domain of the two wave operators and invertibility requirements are stated explicitly.')
item(5,3,'P000013','remark','Generalized probabilities and particle interpretation',r'''Generalized probabilities and a particle interpretation appear as headings in the continuation.''',r'''The notes do not specify a probability algebra, a state, asymptotic particle observables, or a proposed uniqueness criterion. They identify a physical program, not one determinate mathematical statement.''','F',r'''The discussion is thematically connected to the states and quantization in \citet[Parts I and V]{segal1965variete}; an exact result match is not possible.''','The passage remains identifiable only at the level of research program.',refs=['segal1965variete'],literal='not determinable',match='thematic only',confidence='low',development='none')
item(5,4,'P000013','definition','Equal-time canonical commutators',r'''Three equal-time commutators are written; the mixed line has an unclear mark on the second field and an abbreviated delta distribution.''',r'''For smeared scalar fields and conjugate momenta on a common invariant domain, \([\phi(f),\phi(g)]=[\pi(f),\pi(g)]=0\) and \([\phi(f),\pi(g)]=i\hbar\int fg\,dx\,I\). The pointwise notation \([\phi(x),\pi(y)]=i\hbar\delta(x-y)I\) is distributional.''','E',r'''These are the canonical relations used, rather than invented, in \citet[Parts I and III]{segal1965variete}. The scan does not warrant silently replacing every ambiguous mark in the mixed line.''','Established formalism with smearing and domain conditions; field products at coincident points require additional analysis.',refs=['segal1965variete'],literal='correct with missing hypotheses',match='exact',reconstruction='The displayed smeared formulation is an editorial normalization, not a diplomatic emendation of the unclear mark.')
save()

talk(6,'1964-10-05','Laurent Schwartz','P000012-P000018','Radon measures beyond local compactness',r'''Starting on P000013, Schwartz compares abstract measures with Radon measures, pushforwards and completions, compactifications, Radon spaces and stochastic path spaces. The argument separates a cylindrical process law from a Radon law on a suitable function space. Several expansive shorthand claims need restrictions on the topology or a countable family of compact sets.''')
item(6,1,'P000013-P000014','definition','Abstract measures and Radon measures',r'''A countably additive set measure is compared with integration of compactly supported continuous functions and with compact approximation.''',r'''A finite Radon measure on a Hausdorff space is a finite Borel measure inner regular by compact sets. On a locally compact Hausdorff space, positive linear functionals on \(C_c(X)\) give Radon measures with the customary local finiteness. For Banach-valued Bochner integration, strong measurability and integrability of the norm are additional conditions.''','E',r'''The classical foundation is already used by \citet[Sections 1 and 4]{courrege1963mesures}. The later synthesis \citet{schwartz1973radon} was bibliographically verified; its full text was not available in this run.''','Standard measure theory. Positivity, topology, finiteness and the chosen vector-valued integral must be specified.',refs=['courrege1963mesures','schwartz1973radon'],match='partial',reconstruction='A finite-measure convention is fixed to make the subsequent statements unambiguous.')
item(6,2,'P000014','theorem','Pushforward and completion of a Radon measure',r'''For a map \(f:X\to Y\), the notes compare measurability of \(A\subset Y\) with measurability of \(f^{-1}A\), emphasizing completion.''',r'''Let \(\mu\) be a finite Radon measure on a Hausdorff space \(X\), let \(f:X\to Y\) be continuous with \(Y\) Hausdorff, and put \(\nu=f_*\mu\). Then \(A\) is measurable in the completion of \(\nu\) if and only if \(f^{-1}A\) is measurable in the completion of \(\mu\). In the reverse direction compact approximations to the inverse image and its complement give disjoint compact images whose masses exhaust \(\nu(Y)\).''','E',r'''This is part of the Radon-measure framework developed in \citet{schwartz1973radon}; only metadata of that book were checked. The compact approximation argument supplied here verifies the stated continuous-map form directly.''','Valid with the hypotheses displayed. The unrestricted abstract-measure version is false, as the next example demonstrates.',refs=['schwartz1973radon'],verification='indirect',match='partial',reconstruction='Continuity, Hausdorff separation, finiteness and completed sigma algebras are explicit editorial hypotheses.')
item(6,3,'P000014-P000015','construction','A non-Radon image loses measurability information',r'''A nonmeasurable subset of an interval, of full outer measure, carries the restriction of Lebesgue measure; its inclusion is used to show that inverse-image measurability need not imply image measurability.''',r'''Choose a non-Lebesgue-measurable \(X\subset[0,1]\) of outer measure one and define \(\mu(X\cap B)=m(B)\) for Borel \(B\). This is well defined because the complement of \(X\) has inner measure zero. For inclusion \(i\), \(i_*\mu=m\), but \(i^{-1}([0,1]\setminus X)=\varnothing\), although \([0,1]\setminus X\) is not Lebesgue measurable. The source measure is not Radon.''','E',r'''The example illustrates the precise issue in \citet{schwartz1973radon}; the later book is a thematic source with checked metadata, while the set-theoretic verification here is explicit.''','A valid counterexample once non-Lebesgue-measurability is required; being non-Borel alone would not suffice.',refs=['schwartz1973radon'],literal='correct with missing hypotheses',verification='indirect',match='thematic only',reconstruction='The complement itself supplies the required nonmeasurable set, avoiding the false implication non-Borel implies nonmeasurable.')
item(6,4,'P000015-P000016','theorem','Compact regularity and compactification',r'''A space is embedded in a compact space by continuous functions, and Radon measures are described by compact approximation. One displayed quantifier ranges over compact sets where Borel sets are needed.''',r'''For a completely regular Hausdorff space, the Stone--Čech compactification extends every bounded continuous real function. A finite Borel measure is Radon exactly when every Borel set is approximated from inside by compact sets. When a measure is represented on a compactification, concentration on the original space must be expressed using outer measure if that space is not measurable.''','E',r'''\citet[Theorem 1.1 and Section 4]{courrege1963mesures}, a lecture of 6 June 1963, supplies the relevant compactification method. It explicitly uses bounded functions.''','Established. Compact approximation of compact sets alone is tautological and cannot define Radon regularity.',refs=['courrege1963mesures'],literal='false as written',match='partial',reconstruction='Boundedness and the Borel-set quantifier repair the compressed statements.')
item(6,5,'P000016','definition','Radon spaces and universal measurability',r'''A Radon space is one on which every abstract measure is Radon. A subset of a Radon space is Radon precisely when universally measurable; analytic and Suslin examples are mentioned.''',r'''Under the Hausdorff, finite-Borel-measure convention, a Radon space is one on which every finite Borel measure is inner regular by compact sets. Universal measurability means measurability in every completed finite Radon measure. Suslin subspaces of Hausdorff spaces are universally measurable for Radon measures. The equivalence for subspaces needs the stated ambient Radon and subspace-topology assumptions.''','E',r'''These are the Radon/Suslin principles synthesized in \citet{schwartz1973radon}. The notebook is an early exposition, but exact theorem-by-theorem priority was not established from the later metadata.''','Established framework; ``every abstract measure'' cannot mean every measure on every unrelated sigma algebra.',refs=['schwartz1973radon'],match='partial',verification='indirect',confidence='medium',reconstruction='The sigma algebra and meaning of universal measurability are specified.')
item(6,6,'P000016','claim','Function spaces and spaces of operators as Radon spaces',r'''Separable Fréchet spaces, countable inductive limits, duals and \(\operatorname{Hom}(E,F)\) are grouped together; weak, strong and compact-convergence topologies are mentioned.''',r'''Separable Fréchet spaces are Polish and hence Radon. The standard test-function and distribution spaces fit the Suslin/Radon theory with their customary locally convex topologies. More general assertions about inductive limits and operator spaces require specification of regularity, separability and topology; \(\operatorname{Hom}(E,F)\) need not itself be a Fréchet space.''','E',r'''The thematic source is \citet{schwartz1973radon}; its metadata confirm the scope, but no precise universal theorem matching all the shorthand topologies was read. The safe Polish-space case is isolated here.''','The named standard examples are accounted for; an arbitrary countable inductive limit or arbitrary operator topology is not covered by the literal statement.',refs=['schwartz1973radon'],literal='correct with missing hypotheses',match='partial',verification='indirect',confidence='medium',reconstruction='The modern statement intentionally separates a verified elementary subclass from the broader insufficiently specified assertion.')
item(6,7,'P000016-P000017','theorem','Measurability of the continuous-path event',r'''The space of continuous functions is viewed inside \(\mathbb R^{\mathbb R}\), and the probability of continuous sample paths is said always to exist.''',r'''For compact metric \(K\), the inclusion \(C(K)\to\mathbb R^K\), from the uniform topology to the product topology, is continuous; its image is Suslin and therefore measurable for the completion of any Radon Borel measure on the product. A merely cylindrical law from finite-dimensional distributions does not automatically give this event a probability in its cylinder sigma algebra.''','E',r'''This is an application of the Suslin/Radon method described by \citet{schwartz1973radon}. The source identification is thematic rather than a checked numbered theorem.''','Valid for the specified Radon-law setting. The statement must distinguish a law on continuous paths from an arbitrary process on a cylindrical measurable space.',refs=['schwartz1973radon'],literal='correct with missing hypotheses',match='partial',verification='indirect',reconstruction='Compact metric time sets and a completed Radon product law make the assertion precise; continuous paths on the real line are handled on successive compact intervals.')
item(6,8,'P000017','claim','Tightness, compact layers and a common modulus of continuity',r'''A continuous-path law is concentrated on a countable union of compact sets, followed by the assertion that almost all paths have a common modulus.''',r'''A Borel probability on \(C(K)\), for compact metric \(K\), is tight and is concentrated on \(\bigcup_j K_j\) with compact \(K_j\). Each \(K_j\) is bounded and equicontinuous. A single deterministic modulus with coefficient one need not hold almost surely: \(X_t=Zt\) with unbounded \(Z\) is a counterexample. One can use compact-dependent moduli, or a fixed vanishing modulus with an almost surely finite random multiplier.''','E',r'''The compact-layer method is the Radon interpretation in \citet{schwartz1973radon}; the displayed counterexample checks the overstrong notebook conclusion without attributing it to Schwartz as a published theorem.''','The countable compact exhaustion is correct; the unqualified coefficient-one common-modulus assertion is false.',refs=['schwartz1973radon'],literal='false as written',match='partial',verification='indirect',reconstruction='Random multipliers or compact-dependent constants are editorial repairs, not a transcription change.')
save()

talk(7,'1964-10-12','Laurent Schwartz','P000016-P000018','Hilbert subspaces and positive kernels',r'''The actual mathematical exposition begins on P000018 and continues through P000022, beyond the catalogue span. Hilbert spaces continuously injected into a locally convex space form an ordered cone, identified with positive kernels. Distribution and Sobolev examples explain how this language recovers weak existence theorems. The correspondence was already presented in Schwartz’s 1962 Bourbaki lecture.''')
item(7,1,'P000018','definition','Hilbert subspaces of a locally convex space',r'''\(\operatorname{Hilb}(E)\) consists of Hilbert spaces contained in \(E\), with inclusion continuous; the inclusion need not be a topological embedding onto its image.''',r'''For a Hausdorff locally convex space \(E\), a Hilbert subspace is a Hilbert space \(H\) with a continuous injective linear map \(i:H\to E\), identified with its image but carrying its Hilbert norm. Equality includes equality of that norm, not only of the underlying set.''','E',r'''\citet[Section 1]{schwartz1962hilbert} presented this in May 1962, before the Moscow lecture.''','Established definition; an unbounded inverse to the inclusion is permitted.',refs=['schwartz1962hilbert'],literal='correct',match='exact')
item(7,2,'P000018-P000019','construction','Scalar multiplication and the Hilbert quotient sum',r'''Multiplication rescales the inner product by \(1/\lambda\); the sum norm is the infimum of the sum of squared norms, but the square on the left is absent.''',r'''For \(a>0\), \(aH\) has \(\|h\|_{aH}^2=a^{-1}\|h\|_H^2\). For two continuously injected Hilbert spaces, \(H_1+H_2\) is the quotient of \(H_1\oplus H_2\) by the closed kernel of addition, with \(\|h\|^2=\inf_{h=h_1+h_2}(\|h_1\|_1^2+\|h_2\|_2^2)\). Set \(0H=\{0\}\).''','E',r'''These operations are given in \citet[Section 1]{schwartz1962hilbert}. The missing square is confirmed by the norm homogeneity.''','Well-defined Hilbert-cone operations; the infimum is attained by orthogonal projection in the direct sum.',refs=['schwartz1962hilbert'],literal='false as written',match='exact',reconstruction='The norm square and the zero scalar convention are made explicit.')
item(7,3,'P000019-P000020','theorem','Contractive order and the cancellative cone',r'''The order is inclusion with norm at most one. The cone is called strictly convex, and subtraction is described through a unique positive remainder.''',r'''Define \(H_1\le H_2\) when the inclusion is contractive. Under the kernel correspondence this is positive-operator order, and \(H_2=H_1+H_3\) for a unique Hilbert subspace \(H_3\) exactly when \(H_1\le H_2\). The cone is pointed and cancellative. It is not strictly convex in the usual geometric sense: positive semidefinite matrices already have nontrivial faces.''','E',r'''\citet[Sections 1--2, Theorem 1]{schwartz1962hilbert} uses a pointed convex cone. This supplies the meaning behind the notebook terminology.''',r'Established order structure. The scalar comparison \(aH\ge H\iff a\ge1\) needs \(H\ne0\).',refs=['schwartz1962hilbert'],literal='correct with missing hypotheses',match='exact',reconstruction='Pointedness replaces the potentially misleading modern reading of strict convexity.')
item(7,4,'P000020-P000021','theorem','The Hilbert-subspace/positive-kernel correspondence',r'''The inclusion \(i\) is composed with its adjoint to form a positive operator from the antidual, and conversely a positive kernel is completed to recover a Hilbert space.''',r'''For a quasi-complete Hausdorff locally convex \(E\), a Hilbert subspace \(i:H\to E\) determines the positive Hermitian kernel \(K=ii^*:E^{\prime}_{\!a}\to E\), with the compatible weak topologies. Conversely such a continuous positive kernel determines a unique Hilbert subspace, obtained by completing its range modulo its null space with \((K\phi,K\psi)_H=\langle K\phi,\psi\rangle\).''','E',r'''The exact match is \citet[Theorem 1, printed p. 257]{schwartz1962hilbert}, announced in May 1962. Quasi-completeness is used to realize the completion inside \(E\).''','Established and widely applicable; the appropriate antidual convention avoids a hidden complex conjugation error.',refs=['schwartz1962hilbert'],match='exact',reconstruction='The topology and completeness assumptions in the published theorem are restored.')
item(7,5,'P000021-P000022','theorem','Weak boundedness and completion of a Hilbert kernel',r'''A theorem attributed to Mackey says weakly bounded sets are bounded; the Hilbert unit ball is shown weakly bounded during the completion argument.''',r'''In a Hausdorff locally convex space, a subset bounded for the weak topology \(\sigma(E,E')\) is bounded for the original topology. Applied to the kernel unit ball, this gives continuity estimates; quasi-completeness of \(E\) then prevents the Hilbert completion from leaving the ambient space.''','E',r'''This functional-analytic step is used in \citet[proof of Theorem 1]{schwartz1962hilbert}; it is an older boundedness theorem, not a new claim of the seminar.''','Established. Weak boundedness alone is not weak compactness, and completion still requires its separate hypothesis.',refs=['schwartz1962hilbert'],literal='correct',match='exact')
item(7,6,'P000022','construction','Positive distribution kernels and Sobolev examples',r'''For \(E=\mathcal D'\), positive kernels are distributions in two variables; \(L^2\), \(H^1\), \(H^{-1}\) are examples. The notebook assigns \(-\Delta+\lambda\) to \(H^1\).''',r'''A positive distribution kernel \(K\in\mathcal D'(\mathbb R^n\times\mathbb R^n)\) satisfies \(K(\phi\otimes\overline\phi)\ge0\) and gives the corresponding Hilbert subspace of distributions. For \(H^1\) with norm \(\int(\lambda|u|^2+|\nabla u|^2)\), \(\lambda>0\), the associated operator is \((\lambda-\Delta)^{-1}\). The operator \(\lambda-\Delta\) instead corresponds to the reciprocal Sobolev weight.''','E',r'''The distribution-kernel examples belong to \citet[Section 3]{schwartz1962hilbert}. The inverse is also checked directly from the Fourier multiplier.''',r'The positive-kernel correspondence is established. Omitting \(\lambda\) on all of Euclidean space changes to a homogeneous space and needs separate low-frequency treatment.',refs=['schwartz1962hilbert'],literal='false as written',match='exact',reconstruction='The inverse operator is an emendation of a faithfully transcribed formula.')
item(7,7,'P000022','method','Hilbert representation of weak elliptic solutions',r'''The talk ends by saying the Hilbert-subspace construction yields existence theorems for generalized solutions, mentioning domain Sobolev spaces.''',r'''A precise representative case is: on a bounded domain \(\Omega\), a continuous coercive sesquilinear form \(a\) on \(H_0^1(\Omega)\) gives, for each \(f\in H^{-1}(\Omega)\), a unique \(u\in H_0^1(\Omega)\) with \(a(u,v)=\langle f,v\rangle\) for every \(v\). For Hermitian positive \(a\), the inverse is a positive kernel in the Hilbert-subspace framework.''','E',r'''\citet[applications following Theorem 1]{schwartz1962hilbert} gives the Hilbert-kernel context. The notebook has no particular coefficients or boundary problem to match more exactly.''','Established coercive weak-solution method. Noncoercive equations need additional Fredholm or spectral hypotheses.',refs=['schwartz1962hilbert'],match='partial',reconstruction='The displayed variational problem is an explicitly chosen representative example, not a recovered verbatim theorem.')
save()

talk(8,'1964-10-12','S. G. Gindikin','P000016-P000024','Weil rigidity and group cohomology',r'''The actual note is on P000017, between the Radon discussion and the Hilbert-kernel lecture. Gindikin reports Weil’s local rigidity argument, its cohomological criterion, and a dimension formula for surface groups. The brief nondiscrete-subgroup aside lacks a usable hypothesis list.''')
item(8,1,'P000017','theorem','Local rigidity of cocompact semisimple lattices',r'''A semisimple Lie group without a real two-by-two matrix factor and a discrete \(\Gamma\) with compact \(G/\Gamma\) are introduced. All small deformations are said to be conjugate.''',r'''For a connected semisimple real Lie group with finite center and no compact factors or simple factor locally isomorphic to \(\mathrm{SL}_2(\mathbb R)\), a uniform lattice is locally rigid: sufficiently nearby embeddings in \(G\) are conjugate by an element of \(G\). The topology is pointwise convergence on a finite generating set.''','E',r'''\citet[Section 3, discussion after its local-rigidity theorem]{weil1964cohomology} relates the cohomological argument to his earlier rigidity papers. The July 1964 paper preceded the October report.''','Established local rigidity in this scope. The excluded surface-group case has a nontrivial deformation space.',refs=['weil1964cohomology'],match='exact',reconstruction='Finite center, absence of compact factors and the precise local-isomorphism exception give a safe standard formulation of the shorthand.')
item(8,2,'P000017','theorem','Vanishing of H1 implies local rigidity',r'''The sufficient condition is \(H^1(\Gamma,\mathfrak g)=0\), with \(\Gamma\) acting through the adjoint representation.''',r'''For a finitely generated group \(\Gamma\), a real Lie group \(G\), and a homomorphism \(\rho:\Gamma\to G\), if \(H^1(\Gamma,\mathfrak g_{\operatorname{Ad}\rho})=0\), every sufficiently close homomorphism is conjugate to \(\rho\). Cocycles describe the infinitesimal relation equations; coboundaries describe infinitesimal conjugation.''','E',r'''This is the theorem at the end of Section 3 of \citet{weil1964cohomology}, published July 1964.''',r'Established sufficient criterion. Nonzero \(H^1\) alone does not guarantee integrability of every infinitesimal deformation.',refs=['weil1964cohomology'],literal='correct with missing hypotheses',match='exact')
item(8,3,'P000017','remark','The nondiscrete-subgroup aside',r'''The note says that for nondiscrete \(\Gamma\) the theorem can hold although \(H^1\ne0\). No topology or subgroup class is added.''',r'''No single theorem is determined: continuous cohomology of a topological subgroup and abstract group cohomology are different, as are deformations of embeddings and of homomorphisms.''','F',r'''\citet[Section 4]{weil1964cohomology} discusses cases with nonzero cohomology, but the source does not justify identifying those cases with the notebook word ``nondiscrete.''''','The aside remains unresolved at the level of identification; it is not a new open rigidity problem.',refs=['weil1964cohomology'],literal='not determinable',match='thematic only',confidence='low')
item(8,4,'P000017','theorem','Dimension of first cohomology of a surface group',r'''For a \(d\)-dimensional representation a formula \((2g-2)d+i+i'\) is given for the first cohomology dimension.''',r'''Let \(\Gamma=\pi_1(\Sigma_g)\), \(g\ge2\), and let \(V\) be a finite-dimensional characteristic-zero representation. Then \(\dim H^1(\Gamma,V)=(2g-2)\dim V+\dim V^\Gamma+\dim(V^*)^\Gamma\), by Euler characteristic and Poincaré duality with local coefficients.''','E',r'''The torsion-free compact-surface case of \citet[Sections 4--6]{weil1964cohomology} gives this formula; the paper also treats punctures and elliptic generators, whose extra terms are absent here.''','Established. The two invariant-space terms are essential and need not vanish.',refs=['weil1964cohomology'],match='exact',reconstruction=r'The two invariant dimensions, compactness and the absence of orbifold generators are supplied.')
save()

talk(9,'1964-10-19','A. Ya. Povzner','P000022-P000024','Thermodynamic potentials and Wigner distributions',r'''After a brief Kostant bibliographic remark, the notes on P000024--P000025 compare canonical and microcanonical thermodynamics and then introduce the phase-space expression now called the Wigner distribution. Temperature factors and concavity signs require care. The Wigner marginals do not make it a positive classical joint probability.''')
item(9,1,'P000024','remark','The Kostant multiplicity reference',r'''An unattributed preliminary line points to Kostant, volume 93, page 53, 1959, concerning representations of Lie algebras.''',r'''The bibliographic coordinates identify Kostant’s weight-multiplicity paper: for a finite-dimensional irreducible highest-weight representation of a complex semisimple Lie algebra, multiplicities are an alternating Weyl-group sum of the positive-root partition function.''','E',r'''\citet{kostant1959multiplicity} is exactly Transactions of the AMS 93(1), 53--73; the opened Math-Net record verifies these coordinates. The seminar note contains no displayed multiplicity formula.''','Secure identification of the reference; the speaker of the preliminary line is not established.',refs=['kostant1959multiplicity'],literal='correct',match='exact',verification='publisher metadata checked',reconstruction='The mathematical description comes from the identified title and classical result, not an extra notebook formula.')
item(9,2,'P000024','definition','Canonical free energy and thermodynamic derivatives',r'''The canonical partition integral is written with \(1/N!\), followed by a per-particle minus log and formulas for pressure and entropy.''',r'''For a stable finite-volume classical Hamiltonian \(H_N\), \(Z_N=(N!h^{dN})^{-1}\int e^{-H_N/T}\,dq\,dp\). Physical Helmholtz free energy is \(F_N=-T\log Z_N\), with \(S_N=-\partial_TF_N\) and \(p_N=-\partial_VF_N\) when derivatives exist. The reduced quantity \(-\log Z_N/N\) is \(F_N/(NT)\), not \(F_N/N\).''','E',r'''These are standard canonical definitions used in the setting of \citet[Section 1]{dobrushin1965phase}; the continuum integral here is not a claim that the lattice paper proves every continuum thermodynamic limit.''','Correct with a consistent temperature convention. A thermodynamic-limit assertion for general pair potentials additionally needs stability and short-range/temperedness assumptions.',refs=['dobrushin1965phase'],literal='correct with missing hypotheses',match='thematic only',reconstruction='Boltzmann’s constant is set to one and the physical versus reduced free energies are separated.')
item(9,3,'P000024-P000025','definition','Microcanonical entropy and phase volume',r'''The logarithm of the phase volume below an energy is introduced as entropy; convexity and a kinetic \(\log T\) term are mentioned.''',r'''For \(\Omega_N(E,V)=(N!h^{dN})^{-1}\int_{H_N\le E}dq\,dp\), the microcanonical entropy is \(S_N=\log\Omega_N\) (up to convention-dependent constants and surface-volume choices). In a regular thermodynamic limit for short-range stable systems the entropy density is concave in the extensive densities; canonical free energy is its Legendre--Fenchel transform. Integrating quadratic momenta contributes \((dN/2)\log T\) to \(\log Z_N\).''','E',r'''The concavity/phase-coexistence framework is the same thermodynamic setting used in \citet{dobrushin1965phase}. No specific new equivalence-of-ensembles theorem is stated in the notebook.''',r'Established with the required limit hypotheses; the sign of a kinetic term changes when passing from \(\log Z\) to a minus-log potential.',refs=['dobrushin1965phase'],literal='correct with missing hypotheses',match='thematic only',reconstruction='Concavity and ensemble conventions are corrected explicitly rather than merging the two potentials.')
item(9,4,'P000025','construction','Wigner quasidistribution and its marginals',r'''A Fourier integral of \(\psi(x+\tau/2)\overline{\psi(x-\tau/2)}\) is proposed to recover the position and momentum densities.''',r'''For a normalized Schwartz function \(\psi\), \(W_\psi(x,p)=(2\pi\hbar)^{-d}\int e^{-ip\cdot y/\hbar}\psi(x+y/2)\overline{\psi(x-y/2)}\,dy\). Its marginals are \(|\psi(x)|^2\) and the momentum density in the matching Fourier normalization. It is real but may be negative; the two marginals alone do not uniquely characterize it.''','E',r'''\citet{wigner1932quantum}, received 14 March and published 1 June 1932, introduced this phase-space construction. Publisher metadata and abstract were checked; the full article was behind an access restriction.''','An established quasiprobability representation, not a positive classical joint law of position and momentum.',refs=['wigner1932quantum'],literal='correct with missing hypotheses',match='exact',verification='publisher metadata checked',reconstruction='The Fourier normalization, regularity assumptions and nonuniqueness from marginals are supplied.')
save()

talk(10,'1964-10-12','V. I. Arnold','P000022-P000026','Kushnirenko’s entropy bound',r'''P000023--P000024 reports Kushnirenko’s estimate of measure entropy by hypersurface expansion, with a partition-boundary argument. His short paper was received on 1 October and presented by Kolmogorov on 7 October 1964, before this report; publication followed in 1965. The notebook’s sharper invertible estimate is distinguished from the theorem explicitly proved in that announcement.''')
item(10,1,'P000023','definition','Partition entropy and Kolmogorov--Sinai entropy',r'''For a partition \(\xi\), \(-\sum p_i\log p_i\) is followed by the entropy growth of successive refinements and the supremum over partitions.''',r'''For a probability-preserving transformation \(T\) and a finite measurable partition \(\xi\), \(h_\mu(T,\xi)=\lim_{n\to\infty}n^{-1}H_\mu(\bigvee_{j=0}^{n-1}T^{-j}\xi)\). The limit exists by subadditivity and \(h_\mu(T)=\sup_\xi h_\mu(T,\xi)\). Fixing the logarithm base fixes the entropy unit.''','E',r'''\citet[opening definitions and cited Rokhlin survey]{kushnirenko1965entropy} uses this already established definition. His announcement uses logarithms to base two.''','Standard definition; forward images of partitions require invertibility, whereas inverse-image refinements work for endomorphisms.',refs=['kushnirenko1965entropy'],literal='correct with missing hypotheses',match='exact')
item(10,2,'P000023-P000024','theorem','Finite entropy bounded by hypersurface expansion',r'''For a smooth transformation preserving Riemannian volume, \(h(T)\le n\log\lambda\), where \(\lambda\) bounds \((n-1)\)-area expansion.''',r'''Let \(T\) be a volume-preserving smooth diffeomorphism of a compact \(n\)-dimensional Riemannian manifold, with normalized volume. If every smooth hypersurface piece satisfies \(S(TA)\le\lambda S(A)\), then \(h_\mu(T)\le n\log_2\lambda\) in bits. For endomorphisms the sufficient bound concerns the full inverse image \(T^{-1}A\), not only the forward image.''','B',r'''Exact match: \citet[Theorem 1, pp. 37--38]{kushnirenko1965entropy}; received 1 October 1964, presented 7 October, published 1965. Arnold is thanked for posing the problem.''','Established upper bound. The constant is an area-expansion bound, not automatically the ordinary Lipschitz constant.',refs=['kushnirenko1965entropy'],match='exact',reconstruction='The forward/preimage distinction and logarithm base are restored.')
item(10,3,'P000024','claim','Boundary proof and the sharper invertible estimate',r'''The boundary of a joined partition is estimated, and for invertible maps the coefficient \(n-1\) is proposed in place of \(n\).''',r'''For a volume-preserving \(C^1\) diffeomorphism, a bound \(\|\wedge^{n-1}DT\|\le\lambda\) implies \(\|DT^{-1}\|\le\lambda\). Lyapunov exponents sum to zero; each negative exponent has magnitude at most \(\log\lambda\), and there are at most \(n-1\) negative exponents unless all vanish. Ruelle’s inequality therefore yields \(h_\mu(T)\le(n-1)\log\lambda\).''','B',r'''\citet[p. 38]{kushnirenko1965entropy} proves the coefficient \(n\) and mentions examples attaining \((n-1)\log\lambda\), but does not state the general improved theorem. The later differential-entropy inequality of \citet{ruelle1978inequality} gives the displayed refinement; this is a mathematical implication, not a claim of direct historical dependence.''','The refined bound is established by the stated later route. The notebook does not contain the needed Lyapunov-exponent argument.',refs=['kushnirenko1965entropy','ruelle1978inequality'],match='partial',reconstruction='The modern proof route through exponents is editorial; the announced 1965 theorem is kept separate.',verification='read the result')
item(10,4,'P000023','remark','Entropy as forgetting and the strength of mixing',r'''Entropy is glossed as the rate at which the initial state is forgotten; a line places zero near weak mixing and infinity near strong mixing.''',r'''Metric entropy is an asymptotic information-production rate of finite observations. Strong mixing is a separate asymptotic decorrelation property; neither an entropy value nor a linear scale of entropy classifies mixing strength.''','F',r'''\citet{kushnirenko1965entropy} proves a numerical entropy bound and does not supply the suggested universal hierarchy of mixing. No precise theorem is determined by the drawing.''','The mnemonic should remain a mnemonic; it is not a quantitative equivalence.',refs=['kushnirenko1965entropy'],literal='not determinable',match='none found',confidence='medium')
save()

talk(11,'1964-10-19','A. A. Kirillov','P000024-P000026','Announcement of Thoma’s character theory',r'''A short paragraph on P000025 points to Thoma’s 1964 work on countable groups, including the rational affine group. Kirillov develops the topic at length on 2 November, record 13. The normalized tracial notion of character must be distinguished from an arbitrary irreducible unitary representation.''')
item(11,1,'P000025','remark','Thoma characters and the rational affine group',r'''Thoma, Mathematische Zeitschrift volume 84, and the group \(x\mapsto ax+b\) with rational coefficients are mentioned.''',r'''For a countable discrete group, normalized positive-definite conjugation-invariant functions form a compact convex set. Its extreme points correspond via the GNS construction to finite-factor representations with a normalized trace. For finite-dimensional factors these are normalized irreducible characters; the general finite-factor case includes type \(\mathrm{II}_1\).''','E',r'''The coordinates identify \citet{thoma1964classes}, Math. Z. 84, 389--402. Its metadata were opened; the modern definition and factor distinction were read in \citet[Definition 1.1 and following discussion]{petersonthom2016characters}.''','Established character theory, developed in record 13; it does not classify the entire unitary dual of a non-type-I group.',refs=['thoma1964classes','petersonthom2016characters'],match='exact',reconstruction='The finite-factor interpretation resolves the compressed phrase ``irreducible characters.''')
save()

talk(12,'1964-10-19','Laurent Schwartz','P000024-P000030','Smooth vectors, invariant distributions and fundamental solutions',r'''On P000025--P000028 Schwartz passes from smoothing in representations to Lorentz-invariant distributions and differential equations on groups. The notes distinguish the solvable Lorentz case from the general invariant-solution question and then discuss global fundamental solutions, with a torus obstruction. The latter has both a constant-mode obstruction and a separate small-divisor obstruction.''')
item(12,1,'P000025-P000026','theorem','Smooth vectors and smoothing by test functions',r'''A group representation is averaged against a smooth compactly supported function to produce differentiable vectors; Haar measure is called two-sided.''',r'''For a strongly continuous representation \(\pi\) of a Lie group on a Banach space, \(\pi(f)v=\int f(g)\pi(g)v\,dg\), \(f\in C_c^\infty(G)\), is a smooth vector, and an approximate identity proves density of smooth vectors. A left Haar measure suffices; it is bi-invariant only for a unimodular group.''','E',r'''This is the smoothing mechanism of \citet{garding1947continuous}, communicated in August and published in November 1947. The opened primary archive verifies its original publication; the PDF endpoint did not return full searchable text.''','Established Gårding-density construction; bi-invariance is not available for every Lie group.',refs=['garding1947continuous'],match='exact',verification='publisher metadata checked',reconstruction='Strong continuity and a left Haar convention replace the unnecessary two-sided assumption.')
item(12,2,'P000026-P000027','construction','Distribution vectors and the rigged representation space',r'''Smooth vectors, their duals and delta-like vectors are used to enlarge the representation and differentiate the group action.''',r'''For a continuous unitary representation on \(H\), give \(H^\infty\) its seminorms \(v\mapsto\|d\pi(D)v\|\), \(D\) in the enveloping algebra. Its continuous antidual \(H^{-\infty}\), formed using the contragredient representation, gives \(H^\infty\subset H\subset H^{-\infty}\). Lie-algebra operators act continuously in this distribution-vector sense.''','E',r'''The smoothing basis goes back to \citet{garding1947continuous}; the notebook adds the familiar distributional extension. The exact strong-topology assertion about all orbit maps is not used here.''','Standard rigged-space construction with the stated topology and dual convention.',refs=['garding1947continuous'],match='partial',verification='indirect',reconstruction='The contragredient antidual and seminorm topology are editorial specifications.')
item(12,3,'P000027','theorem','Lorentz-invariant inhomogeneous wave equations',r'''For Lorentz-invariant \(A\), the notes assert a Lorentz-invariant solution of \(\Box X=A\), reducing away from the origin to distributions in a quadratic invariant.''',r'''For the proper Lorentz group on Minkowski space of dimension at least three, invariant distribution theory must distinguish spacelike and timelike orbits and the two time orientations. Reduction to a single unrestricted expression \(T(q)\) is too compressed on the light cone and at the origin. A precise invariant-solution theorem requires this orbit-distribution framework.''','E',r'''\citet{methee1954lorentz}, received October 1953 and published December 1954, studies exactly Lorentz-invariant distributions and wave equations. Its metadata and introductory scope were checked; the complete theorem supporting every inhomogeneous datum was not retrieved.''','The topic is identified as prior invariant-distribution theory; this entry does not assert an unread blanket surjectivity theorem.',refs=['methee1954lorentz'],literal='correct with missing hypotheses',match='partial',verification='indirect',confidence='medium',reconstruction='The modern statement describes the necessary framework and the precise verification limit rather than inventing a theorem number.')
item(12,4,'P000027-P000028','method','Extension across the origin and a cohomological obstruction',r'''The invariant distribution is extended across the exceptional point, and a finite-dimensional semisimple-group representation is said to have a fixed point.''',r'''Suppose a distribution on the punctured space has an extension of bounded order. The difference between its transforms and itself is then a continuous 1-cocycle with values in a finite-dimensional space of delta derivatives, once a common finite-order bound is established. For a connected semisimple group in characteristic zero, the vanishing of this finite-dimensional first cohomology permits an invariant extension. The fixed-point assertion concerns an affine action; every linear representation already fixes zero.''','E',r'''The extension problem is part of the setting of \citet{methee1954lorentz}. The finite-dimensional cohomological correction is a reconstruction of the notebook argument; exact theorem identification remains indirect.''','Valid conditional mechanism. Establishing extension and a uniform jet-order bound is an essential analytic step, not a consequence of the word ``distribution'' alone.',refs=['methee1954lorentz'],match='partial',verification='indirect',confidence='medium',reconstruction='The affine cocycle, finite jet space and extension hypothesis make the proof mechanism explicit.')
item(12,5,'P000027','problem','Does invariant data admit an invariant solution?',r'''After the Lorentz example the notes ask for the analogous assertion for an arbitrary group and invariant differential operator, noting the lack of compact averaging.''',r'''If a compact group acts continuously and \(P\) commutes with that action, averaging any solution of \(Pu=f\) with invariant \(f\) gives an invariant solution. For noncompact groups this is false in general: let translations of \(\mathbb R\) act on distributions, take \(P=d/dx\) and \(f=1\). The equation has solutions \(x+C\), while translation-invariant distributions are constant and are killed by \(P\).''','E',r'''The compact averaging principle and elementary translation obstruction settle the unrestricted question; \citet{methee1954lorentz} concerns a special noncompact action where additional structure matters. No universal positive theorem is inferred from that example.''','The unrestricted assertion is false; useful versions require assumptions on the action, operator and representation.',refs=['methee1954lorentz'],match='partial',verification='indirect',reconstruction='The explicit translation counterexample is an editorial check of the quantifiers, not a claimed later theorem by Schwartz.',problem='GP-1964-A01')
item(12,6,'P000028','problem','Fundamental solutions for invariant differential operators',r'''For a polynomial \(P(X_1,\ldots,X_n)\) in invariant vector fields on a Lie group, the problem is to find \(E\) with \(PE=\delta_e\). A positive conjecture for noncompact groups is suggested.''',r'''Global existence is not automatic. On a compact group, a nontrivial kernel of the transpose already obstructs \(PE=\delta_e\). On noncompact groups, complex invariant operators can fail even local solvability, as in the Heisenberg-group form of the Lewy operator. Constant-coefficient operators on \(\mathbb R^n\) form the positive Malgrange--Ehrenpreis case, not the general case.''','B',r'''\citet[Introduction and Theorem 1 in Section 4]{cerezo1969fundamental} gives a precise compact-group Fourier criterion; \citet[Section 1]{lerner2000solvability} records the Lewy obstruction and its distributional strengthening. The latter was known by 1960, before this broad conjectural suggestion.''','The universal noncompact conjecture is false. The compact case and many specified operator classes have precise criteria; there is no single unconditional group-wide existence theorem.',refs=['cerezo1969fundamental','lerner2000solvability'],literal='false as written',match='partial',reconstruction='Local and global solvability, real and complex coefficients, and the compact obstruction are separated.',problem='GP-1964-A02')
item(12,7,'P000028','problem','Torus fundamental solutions and small divisors',r'''An irrational first-order vector field on a torus is said to lack an elementary solution; the note contrasts compact groups with noncompact ones.''',r'''On \(\mathbb T^2\), \(L=\partial_x-\alpha\partial_y\) never has \(LE=\delta_0\), since the left side annihilates constants. For irrational \(\alpha\), the reduced equation \(LE=\delta_0-1\), with normalized Haar measure, has a distribution solution exactly when \(|m-\alpha n|\ge C(1+|m|+|n|)^{-N}\) for all nonzero integer pairs and some \(C,N>0\). Thus the reduced problem distinguishes non-Liouville from Liouville slopes.''','B',r'''\citet[Theorem and Proposition, pp. 112--114]{greenfield1972global} gives the polynomial-symbol criterion and the irrational-slope classification; received November 1970, revised March 1971, published January 1972. The full author-deposited article was read.''','The precise Fourier problem is settled. The notebook objection to a delta fundamental solution holds for every slope because of the constant mode, independently of small divisors.',refs=['greenfield1972global','cerezo1969fundamental'],literal='correct with missing hypotheses',match='exact',reconstruction='The reduced right-hand side is an explicit modern refinement, not what the notebook literally writes.',problem='GP-1964-A02')
save()

talk(13,'1964-11-02','A. A. Kirillov','P000028-P000036','Thoma characters and representations over different fields',r'''Kirillov reports three 1964 papers of Elmar Thoma, using the affine group over a finite field and over the rationals as examples. The infinite symmetric group and the type-I criterion follow. A question about rational two-by-two matrices leads into a comparison of rank-one character formulae over complex, real, non-Archimedean and finite fields, ending with adeles. The mathematical text begins on P000029 and ends at the top of P000035; the wider catalogue span also contains neighbouring discussions.''')
item(13,1,'P000029','definition','Normalized positive-definite class functions and finite factors',r'''The notes define positive definiteness by the matrices \((f(g_i g_j^{-1}))\), impose conjugacy invariance, and call extreme points characters of irreducible representations. The finite-dimensional example is \(n^{-1}\operatorname{Tr}T(g)\).''',r'''For a countable discrete group \(G\), let \(\operatorname{Char}(G)\) be the convex set of conjugation-invariant positive-definite functions \(\tau:G\to\mathbb C\) with \(\tau(e)=1\). An element is extreme exactly when its tracial GNS representation generates a finite factor. If that factor is \(M_n(\mathbb C)\), it is the normalized character of an irreducible finite-dimensional representation; a type-\(\mathrm{II}_1\) factor supplies an infinite-dimensional example without an ordinary operator trace.''','E',r'''This is the framework of \citet{thoma1964classes}; the original metadata were verified. The precise GNS and factor statement is read in \citet[Definition 1.1 and the following discussion]{petersonthom2016characters}.''','Established. Extreme tracial characters classify the relevant finite-factor representations up to their tracial equivalence, not every irreducible unitary representation of a non-type-I group.',refs=['thoma1964classes','petersonthom2016characters'],match='exact',reconstruction='Normalization and the finite-factor interpretation are made explicit; positivity means positive semidefinite, not necessarily strictly positive.')
item(13,2,'P000029-P000030','theorem','Irreducible representations of the finite affine group',r'''For \(x\mapsto ax+b\) over \(\mathbb F_p\), the notes count \(p-1\) one-dimensional representations and conjecture one more of dimension \(p-1\), then construct it from nonzero additive characters.''',r'''For prime \(p\), the complex irreducible representations of \(G=\mathbb F_p\rtimes\mathbb F_p^\times\) are the \(p-1\) characters \((a,b)\mapsto\chi(a)\), and one representation of dimension \(p-1\) induced from a nontrivial character of the additive normal subgroup. Multiplication acts transitively and freely on its nonzero dual characters. For a generator \(u\) of \(\mathbb F_p^\times\), \(\chi_j(u^r)=e^{2\pi i jr/(p-1)}\); the written \(e^{2\pi i a/p}\) is not a multiplicative character.''','E',r'''The notebook itself completes the finite-group construction. It is the elementary normal-subgroup induction method proved in \citet[Section 1.6]{prasad2007representations}, used here as a check of the classical argument, not as its first publication.''',r'Complete classification. The sum of squared degrees is \((p-1)+(p-1)^2=p(p-1)\), so the displayed list exhausts the irreducibles.',refs=['prasad2007representations'],literal='false as written',match='partial',reconstruction='The multiplicative-character formula and a consistent conjugation convention replace the incompatible additive exponential and eigenvector indices.')
item(13,3,'P000031-P000032','construction','Permutation realization and explicit affine characters',r'''Functions on the finite affine line give a permutation representation; constants are removed, and fixed-point counting produces traces \(0,-1,p-1\). The normalized trace is then sent formally to a limit as \(p\to\infty\).''',r'''Let \(G=\operatorname{Aff}(\mathbb F_p)\) act on functions by \((\pi(g)f)(x)=f(g^{-1}x)\). Its zero-sum subspace is the irreducible representation of dimension \(p-1\), with character \(0\) when \(a\ne1\), \(-1\) when \(a=1,b\ne0\), and \(p-1\) at the identity. Division by \(p-1\) gives the normalized tracial character. The unreduced permutation character counts the one, zero, or \(p\) fixed points respectively.''','E',r'''The formulas follow from the explicit representation in the notebook and the finite-group irreducibility criterion of \citet[Section 1.6]{prasad2007representations}.''','Established finite calculation. A pointwise limit across changing groups requires chosen identifications of the elements; the notebook comparison is a suggestive formula comparison.',refs=['prasad2007representations'],match='partial',reconstruction='The inverse in the action makes it a left representation; the handwritten convention without the inverse is an antirepresentation. The identity row is reconstructed mathematically while its ambiguous source glyph remains logged.')
item(13,4,'P000032','theorem','The rational affine group and the limiting regular character',r'''After the finite table, the notes ask what remains for rational coefficients and display a limiting column equal to one at the identity and zero elsewhere.''',r'''For the discrete group \(G=\mathbb Q\rtimes\mathbb Q^\times\), the extreme normalized tracial characters are the one-dimensional functions \(\tau(a,b)=\chi(a)\), with \(\chi\) a unitary character of the discrete multiplicative group, and the regular character \(\delta_e\). The nonzero translations form one conjugacy class. For an extreme trace, the projection onto translation-fixed vectors is central in the generated factor, hence is zero or one; in the first case orthogonality of translations forces vanishing away from the identity, and in the second the representation factors through \(\mathbb Q^\times\).''','E',r'''The report identifies \citet{thoma1964classes}, published before the talk, as the source of this example. Its metadata were verified; the brief factor-projection argument supplied here checks the formula without claiming that the unread original uses the same proof.''','The tracial-character classification is settled. It does not imply that the entire unitary dual of the rational affine group admits a comparable finite list.',refs=['thoma1964classes','petersonthom2016characters'],match='exact',verification='indirect',reconstruction='The extremality argument is an editorial verification. The finite-field table does not by itself prove a limiting theorem for rational groups.')
item(13,5,'P000031','method','Spectral decomposition and dynamical systems for affine representations',r'''The translation operators are simultaneously diagonalized; multiplication acts on their characters, and ergodic measures are said to give representations. Vector-valued fibers are explicitly indicated.''',r'''For a unitary representation of a locally compact abelian translation group \(A\), the spectral theorem decomposes the representation over \(\widehat A\), with possible multiplicity spaces. A compatible action of dilations transports this spectral measure and its fibers. A concrete realization therefore includes a quasi-invariant measure class, the associated Radon--Nikodym factors and a measurable unitary cocycle; an ergodic measure alone need not determine the representation.''','E',r'''This is the semidirect-product spectral method underlying the finite construction in \citet[Section 1.6]{prasad2007representations} and the character discussion of \citet{thoma1964classes}. These references confirm the setting; an exact later theorem matching every abbreviated infinite-dimensional assertion was not read.''',r'A standard representation-theoretic framework. The topology on \(\mathbb R\) versus discrete \(\mathbb Q\), multiplicity and cocycle data must be fixed before a classification claim is meaningful.',refs=['prasad2007representations','thoma1964classes'],match='partial',verification='indirect',confidence='medium',reconstruction='The measure-class and multiplicity qualifications make the spectral construction precise. The uncertain Haar-measure abbreviation is not expanded into a theorem.')
item(13,6,'P000032','claim','Restriction to a normal subgroup and extreme points',r'''A normal subgroup \(G_0\) is introduced, followed by a compressed statement that certain extreme points coincide with those for the original group. The exact invariant convex sets and the final abbreviation are unclear.''',r'''Restriction of an extreme normalized character to a normal subgroup need not be extreme among all normalized characters of that subgroup: the normalized two-dimensional irreducible character of \(S_3\) restricts to the average of the two nontrivial characters of \(A_3\). Extremality in a smaller convex set invariant under conjugation by the ambient group is a different statement.''','F',r'''The surrounding reference is \citet{thoma1964classes}, but its original proof was not retrieved and the source does not specify the convex set needed to identify a theorem. The finite counterexample excludes the most literal unrestricted reading.''','The intended lemma is unresolved as a textual identification, not an open theorem about all normal subgroups.',refs=['thoma1964classes'],literal='not determinable',match='none found',verification='unresolved lead',confidence='low',reconstruction='The counterexample is an editorial test of one possible reading; it is not attributed to Thoma.')
item(13,7,'P000032-P000033','theorem','Thoma characters of the infinite symmetric group',r'''For finite-support permutations, the cycle counts \(n_k\) determine conjugacy, and every character is written as \(\prod a_k^{n_k}\). The restrictions on the real numbers \(a_k\) are omitted.''',r'''Let \(S_\infty\) be the group of finite-support permutations of \(\mathbb N\). Its extreme normalized characters are indexed by nonincreasing sequences \(\alpha_i,\beta_i\ge0\) with \(\sum_i\alpha_i+\sum_i\beta_i\le1\), and satisfy \(\chi(\sigma)=\prod_{k\ge2}(\sum_i\alpha_i^k+(-1)^{k-1}\sum_i\beta_i^k)^{n_k(\sigma)}\). Only finitely many factors differ from one; this formula does not describe arbitrary unconstrained real sequences.''','E',r'''The exact source is \citet{thoma1964symmetric}, Math. Z. 85, 40--61 (1964). Its metadata were opened. The full parameter formula and an operator-algebraic proof are read in \citet[Theorem 0.1 and Sections 6--8]{gohm2010characters}, circulated in May 2010.''','Thoma’s classification is established. General normalized characters are mixtures of these extreme characters, so they need not be multiplicative over disjoint cycles.',refs=['thoma1964symmetric','gohm2010characters'],match='exact',reconstruction='The parameter simplex and the restriction to extreme characters supply the essential missing hypotheses.')
item(13,8,'P000033','theorem','Type I countable discrete groups',r'''The notes give a normal subgroup \(G_0\) with finite quotient and insert \ru{изом. G}; they call this necessary and sufficient for type I.''',r'''A countable discrete group is type I exactly when it is virtually abelian. Equivalently it has an abelian normal subgroup of finite index, since one can take the core of any abelian finite-index subgroup. Merely requiring a finite-index subgroup isomorphic to the original group is not a type-I criterion.''','E',r'''This is \citet{thoma1964unitary}, Math. Ann. 153, 111--138, published April 1964 after receipt on 18 January 1963. The metadata and the statement as cited in \citet[Introduction]{petersonthom2016characters} were checked; the full original proof was not retrieved.''','Established classification. The omitted word is mathematically consequential, and the scan does not justify pretending that the manuscript actually says abelian.',refs=['thoma1964unitary','petersonthom2016characters'],literal='false as written',match='exact',verification='indirect',reconstruction='Replace the asserted criterion by virtual abelianness as a mathematical emendation, not a transcription repair.')
item(13,9,'P000033','problem','Characters of rational two-by-two matrix groups',r'''The notes label characters of two-by-two matrices over the rationals as not done. The determinant is not specified in that line, but a later matrix in the same discussion has determinant one.''',r'''For the definite interpretation \(G=\mathrm{SL}_2(\mathbb Q)\) with the discrete topology, classify extreme normalized tracial characters. There are exactly the trivial character and the two functions supported on \(Z(G)=\{\pm I\}\) which take value one at \(I\) and value \(+1\) or \(-1\) at \(-I\). For \(\mathrm{PSL}_2(\mathbb Q)\) the list is the trivial and regular characters.''','B',r'''\citet[Theorem 2.4]{petersonthom2016characters} proves that every nontrivial extreme character of \(\mathrm{SL}_2(k)\), for any infinite field \(k\), is induced from its center. The preprint appeared 16 March 2013, the article online 11 March 2014, and the print issue on 1 July 2016. The theorem and its proof were read.''',r'The stated special-linear interpretation is solved. The unqualified source line does not license silently replacing the group by \(\mathrm{GL}_2(\mathbb Q)\) and claiming that the same theorem is its full classification.',refs=['petersonthom2016characters'],literal='correct with missing hypotheses',match='partial',confidence='high',reconstruction=r'The determinant-one group is an explicit interpretation supported by the later matrix, and the central signs are the specialization of the theorem to \(\mathbb Q\).',problem='GP-1964-A03')
item(13,10,'P000030-P000033','question','A field-uniform functor of characters',r'''Representations and characters are proposed as functors of an unknown field; identities valid over several fields are suggested to hold universally.''',r'''An algebraic group can be a functor on fields, but its complex unitary or tracial character theory additionally depends on the topology of its field of points, the category of representations, parameters and normalization. No category, transition maps or transfer principle for the proposed character functor is specified.''','F',r'''The local formulas compared below and the adelic construction in \citet{gelfand1964adeles} account for the motivation. They do not give a theorem that equality over several fields forces equality over every field.''','A recognisable research programme with insufficient data for a definite mathematical claim or an open-problem status.',refs=['gelfand1964adeles'],literal='not determinable',match='thematic only',verification='unresolved lead',confidence='medium',development='none',reconstruction='No modern transfer theorem or Langlands statement is substituted for the unformalized proposal.')
item(13,11,'P000034','theorem','Complex rank-one distribution characters',r'''For complex matrices of determinant one the notes write a numerator \(\pi(\lambda)+\pi(\lambda^{-1})\) divided by \(|\lambda-\lambda^{-1}|^2\), attributed to Gelfand and Naimark, 1947.''',r'''For the normalized principal series of \(\mathrm{SL}_2(\mathbb C)\) induced by a unitary character \(\chi\) of \(\mathbb C^\times\), its distribution character on a regular semisimple element with eigenvalues \(\lambda,\lambda^{-1}\) is \((\chi(\lambda)+\chi(\lambda^{-1}))/|\lambda-\lambda^{-1}|^2\), with ordinary complex modulus in the denominator. The trace is defined after integration against a test function; it is not an ordinary trace of the individual infinite-dimensional operator.''','E',r'''The notebook’s 1947 attribution is consistent with the historical references in \citet{gelfandgraev1963representations}. Its Section 5.1, equation (5), gives the principal-series formula with the local-field absolute value, which for \(\mathbb C\) is the square of ordinary modulus.''','Established regular-semisimple character formula. Values at the identity or repeated eigenvalues cannot be obtained by substituting directly into this quotient.',refs=['gelfandgraev1963representations'],match='exact',reconstruction='Normalized induction, the distributional meaning and the regular-semisimple domain are supplied; the 1947 original was not separately opened.')
item(13,12,'P000034','theorem','Real rank-one principal and discrete series',r'''The real principal-series expression vanishes for nonreal eigenvalues. A second expression, apparently for a discrete-series family, has an undefined minimum eigenvalue and a row without its condition; the 1947 marginal surname remains unclear.''',r'''For a normalized unitary principal series of \(\mathrm{SL}_2(\mathbb R)\) induced from a character \(\chi\) of \(\mathbb R^\times\), the regular character is \((\chi(\lambda)+\chi(\lambda^{-1}))/|\lambda-\lambda^{-1}|\) on split semisimple elements and zero on elliptic regular elements. The discrete series are additional representations. For a holomorphic discrete series with lowest rotation weight \(k\ge2\), one compatible elliptic boundary-value convention gives \(e^{ik\theta}/(1-e^{2i\theta})\) for \(\theta\notin\pi\mathbb Z\); changing the rotation convention conjugates or reverses this formula.''','E',r'''The principal-series formula is the real specialization of \citet[Section 5.1, equation (5)]{gelfandgraev1963representations}. The discrete-series expression is an explicit modern highest/lowest-weight reconstruction from the geometric series of rotation weights, not a claimed decipherment of the incomplete second brace.''','The representation families and distribution characters are established. The source’s second formula and marginal author cannot be uniquely identified at the same confidence as the principal-series line.',refs=['gelfandgraev1963representations'],literal='not determinable',match='partial',confidence='medium',reconstruction='The distinction between the two families and the displayed rotation-weight convention are editorial. The uncertain surname is retained rather than silently replaced with Bargmann.')
item(13,13,'P000034','theorem','Non-Archimedean principal-series characters',r'''The same quotient is written for a p-adic field, zero when the eigenvalue is not in the base field, and attributed to Gelfand and Graev, 1963.''',r'''Let \(K\) be a non-Archimedean local field of characteristic zero and odd residue characteristic, and let \(\chi\) be a unitary character of \(K^\times\). The normalized induced principal-series character on a regular split semisimple element of \(\mathrm{SL}_2(K)\), with eigenvalues \(\lambda,\lambda^{-1}\), is \((\chi(\lambda)+\chi(\lambda^{-1}))/|\lambda-\lambda^{-1}|_K\); it is zero on regular elliptic elements. At reducibility parameters this is the character of the entire induced representation, not automatically of either irreducible constituent.''','E',r'''Exact source match: \citet[Section 5.1, equation (5)]{gelfandgraev1963representations}, received 8 April 1963 and published in the 1963 survey. The formula and its regularity qualifications were read.''','Established principal-series formula. Supercuspidal and other discrete-series characters are not exhausted by this one line.',refs=['gelfandgraev1963representations'],match='exact',reconstruction='The normalized local absolute value and the distinction between induced and irreducible characters remove hidden conventions; the chosen field range stays within the opened source.')
item(13,14,'P000034','theorem','Finite-field split and nonsplit character formulae',r'''For a finite field, the split formula loses its denominator, and another family has \(-\pi(\lambda)-\pi(\lambda^{-1})\) on nonsplit elements. The margin says Frobenius, 1895.''',r'''For odd \(q\), a generic principal-series character of \(\mathrm{SL}_2(\mathbb F_q)\), induced from \(\chi:\mathbb F_q^\times\to\mathbb C^\times\) with \(\chi^2\ne1\), has value \(\chi(\lambda)+\chi(\lambda^{-1})\) on regular split elements and zero on regular nonsplit elements. A generic cuspidal character associated with a character \(\theta\) of the norm-one torus in \(\mathbb F_{q^2}^\times\), \(\theta^2\ne1\), is zero on regular split elements and \(-\theta(\lambda)-\theta(\lambda^{-1})\) on regular nonsplit elements. Central, unipotent and exceptional parameters require further rows.''','E',r'''The formula is read in \citet[Sections 2.5 and 3.6, especially Exercise 3.44 and Lemma 3.45]{prasad2007representations}, whose construction supplies a modern verification. Its introduction dates the complete finite-group classifications to Jordan and Schur in 1907, so the notebook’s bare Frobenius 1895 label is not used as a verified exact publication citation.''','The finite character theory is established. The two displayed families are not a complete character table without their exceptional and nonregular cases.',refs=['prasad2007representations'],match='exact',reconstruction='The two parameter groups differ: the nonsplit parameter belongs to the norm-one torus, not to the multiplicative group of the base field.')
item(13,15,'P000033','claim','Trace as a proposed conjugacy coordinate',r'''For a determinant-one matrix, the notes say the conjugacy class is determined by \(\alpha+\delta\).''',r'''Over an algebraically closed field, a regular semisimple \(\mathrm{SL}_2\) conjugacy class is determined by its trace. Without regularity, the identity and a nontrivial unipotent matrix both have trace two but are not conjugate. Over a nonclosed field, a stable conjugacy class can split into several rational conjugacy classes, so trace alone is not a universal coordinate.''','E',r'''The explicit split, elliptic, central and unipotent distinctions in \citet[Section 2.4]{prasad2007representations} and \citet[Section 5]{gelfandgraev1963representations} show the missing domain of the notebook assertion.''','The unqualified assertion is false; it is a valid coordinate on the specified regular semisimple algebraically closed setting.',refs=['prasad2007representations','gelfandgraev1963representations'],literal='false as written',match='partial',reconstruction='The regularity and field restrictions are mathematical corrections, not changes to the visible handwriting.')
item(13,16,'P000035','construction','Adeles as a framework for local-field analogies',r'''Adeles are described as a direct sum of all p-adic groups, with the rational numbers as the diagonal.''',r'''The adele ring of \(\mathbb Q\) is \(\mathbb A_{\mathbb Q}=\mathbb R\times\prod_p'\mathbb Q_p\), restricted relative to \(\mathbb Z_p\): all but finitely many finite coordinates are integral, not necessarily zero. The diagonal \(\mathbb Q\) is discrete and cocompact in this full additive adele group. Omitting the real place gives finite adeles, in which \(\mathbb Q\) is dense rather than discrete.''','E',r'''\citet[Section 1, p. 487]{gelfand1964adeles}, received 8 January 1964 and published before the talk, explicitly uses all inequivalent valuations and the restricted-product condition for adelic matrix groups. The definition and diagonal-subgroup statement were read.''','Established local-to-global framework. The literal algebraic direct sum cannot contain the proposed nonzero rational diagonal.',refs=['gelfand1964adeles'],literal='false as written',match='exact',reconstruction=r'Restricted product and the Archimedean place replace the shorthand direct-sum description; additive cocompactness is the standard specialization to \(\mathbb G_a\).')
save()

talk(14,'1964-11-02','I. I. Pyatetskii-Shapiro','P000034-P000036','Linnik’s lattice points on spheres',r'''P000036 reports Linnik’s use of arithmetic dynamics to distribute integer solutions of \(x^2+y^2+z^2=m\) on the sphere. The fixed splitting prime is visible; the source also warns that some radii have few points. The catalogue assigns the report to 2 November, while the preceding page separately announces Linnik for the 16th. The handwritten parenthesis Ilya Iosifovich resolves the speaker’s otherwise merged initials.''')
item(14,1,'P000036','theorem','Admissible integers represented by three squares',r'''The problem asks which \(m\) are sums of three squares and notes the obstruction \(m=8a+7\).''',r'''A positive integer \(m\) is represented by three integral squares exactly when \(m\ne4^a(8b+7)\) for nonnegative integers \(a,b\). The visible mod-eight obstruction is necessary but is only one stage of the complete criterion, since divisibility by four forces all three coordinates even.''','E',r'''This classical theorem predates the seminar. The proof and formulation are part of the arithmetic background to \citet[Section 1]{linnik1957sphere}; a checked modern discussion appears in \citet[Section 1]{ellenberg2012linnik}.''','Established existence criterion. Existence alone does not imply equidistribution as the radius grows: multiplying a fixed radius squared by powers of four preserves the finite set of directions.',refs=['linnik1957sphere','ellenberg2012linnik'],literal='correct',match='partial',reconstruction='The full obstruction and the powers-of-four countersequence supplement the source’s single congruence example.')
item(14,2,'P000036','theorem','Linnik angular equidistribution with a fixed splitting prime',r'''The proportion of lattice points projecting into a region is said to approach its area when \(\xi^2+m\equiv0\pmod q\) is solvable for a fixed prime \(q\).''',r'''Fix a prime \(q>3\). Let \(m\to\infty\) through integers congruent to \(1,2,3,5,6\pmod8\) and satisfying the Legendre-symbol condition \(\bigl(\frac{-m}{q}\bigr)=1\). For a fixed region \(\Omega\subset S^2\) with piecewise smooth boundary, the proportion of points \(x\in\mathbb Z^3\), \(|x|^2=m\), for which \(x/\sqrt m\in\Omega\), tends to \(\operatorname{area}(\Omega)/(4\pi)\). The analogous statement holds for primitive points. Requiring Legendre symbol one also excludes \(q\mid m\), so mere solvability with the zero residue is weaker.''','E',r'''Exact prior match: \citet[Theorem 1, Section 2, p. 258]{linnik1957sphere}, received 11 July 1956 and published 1957. The paper distinguishes all and primitive points in equations (2.1)--(2.2). \citet[pp. 73--74]{duke1988hyperbolic} later removes the fixed splitting-prime restriction by modular-form methods.''',r'The stated theorem is established. In particular, for squarefree admissible \(m\), Duke’s 1988 result gives equidistribution without a fixed splitting prime. No unrestricted assertion along \(m=4^a m_0\) follows.',refs=['linnik1957sphere','duke1988hyperbolic'],match='exact',reconstruction='The admissible congruence classes, fixed prime, nonzero square condition, normalized area and limit are supplied from the original theorem.')
item(14,3,'P000036','method','Arithmetic dynamics from rational orthogonal matrices',r'''Matrices with entries \(a/q\) are used to move integral sphere points; the note says each point has its own 48 orthogonal matrices, then calls the evolution a Markov chain.''',r'''Under the splitting condition, Linnik constructs arithmetic trajectories using rational orthogonal transformations with prime-power denominators, after passing to a fundamental region for the finite integral symmetry group. Choosing a root of \(c^2+m\equiv0\pmod{q^k}\) selects one of two directions in the reduced dynamics. Equidistribution requires arithmetic control of long trajectories and their correlations; it does not follow solely from calling a finite evolution a Markov chain.''','E',r'''\citet[Section 3, pp. 258--260, Theorems 3--4]{linnik1957sphere} gives the deterministic reduced flow and its ergodic/mixing statements. \citet[Sections 2, 8 and 9]{ellenberg2012linnik} develops a graph and random-walk formulation. Neither read source identifies the notebook’s unexplained 48 as a universal transition degree for each prime.''','The arithmetic method is established and has later graph-theoretic refinements. The written 48 is retained as an unresolved combinatorial shorthand: the full integral orthogonal symmetry group has order 48, but this fact does not establish that the manuscript means precisely that group.',refs=['linnik1957sphere','ellenberg2012linnik'],literal='not determinable',match='partial',confidence='medium',reconstruction='The distinction between a deterministic reduced trajectory, integral symmetries and a Markov presentation prevents an unsupported identification of the number 48.')
save()

